import {
	Component,
	Element,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";

/**
 * @since 2.18.34
 * @status beta
 *
 * @description The `hbr-drag-ghost` component provides a customizable ghost image for drag operations.
 *
 * For pointer-based drag preview that moves the actual element, use `hbr-drag-preview` instead.
 *
 * @slot - Used for custom ghost content. If not provided, uses the `content` prop or default styling.
 * @slot icon - Icon slot for custom icon content (e.g. hbr-icon).
 */
@Component({
	tag: "hbr-drag-ghost",
	styleUrl: "drag-ghost.scss",
	// No Shadow DOM so app-side styles can target the ghost element directly.
	shadow: false,
})
export class DragGhost {
	@Element() host: HTMLHbrDragGhostElement;

	/** Text content to display in the ghost. Supports template syntax with {id} placeholder. */
	@Prop() content = "";

	/** X offset for positioning the drag image (pixels from cursor) */
	@Prop() offsetX = 0;

	/** Y offset for positioning the drag image (pixels from cursor) */
	@Prop() offsetY = 0;

	@State() isActive = false;

	/** Resolved content with dragId interpolation */
	@State() resolvedContent = "";

	@State() hasSlottedIcon = false;
	private dragCleanupListenerAdded = false;

	connectedCallback() {
		if (!this.dragCleanupListenerAdded) {
			document.addEventListener("dragend", this.handleGlobalDragCleanup, true);
			document.addEventListener("drop", this.handleGlobalDragCleanup, true);
			this.dragCleanupListenerAdded = true;
		}
	}

	disconnectedCallback() {
		if (this.dragCleanupListenerAdded) {
			document.removeEventListener(
				"dragend",
				this.handleGlobalDragCleanup,
				true,
			);
			document.removeEventListener("drop", this.handleGlobalDragCleanup, true);
			this.dragCleanupListenerAdded = false;
		}
	}

	// ─────────────────────────────────────────────────────────────────────────────
	// PUBLIC METHODS
	// ─────────────────────────────────────────────────────────────────────────────

	/**
	 * Attaches this ghost as the drag image for a drag event.
	 * Must be called synchronously within a dragstart event handler.
	 * @param event - The DragEvent from dragstart
	 * @param dragId - Optional ID to interpolate into content template
	 */
	@Method()
	async attachToEvent(event: DragEvent, dragId?: string): Promise<void> {
		if (!event.dataTransfer) {
			console.warn("hbr-drag-ghost: No dataTransfer on event");
			return;
		}

		// Update resolved content with dragId template
		this.resolvedContent = dragId
			? this.content.replace(/\{id\}/g, dragId)
			: this.content;
		this.isActive = true;

		// Set as drag image - MUST be synchronous within dragstart
		event.dataTransfer.setDragImage(
			this.host,
			this.offsetX || this.host.offsetWidth / 2,
			this.offsetY || this.host.offsetHeight / 2,
		);
	}

	// ─────────────────────────────────────────────────────────────────────────────
	// EVENT HANDLERS
	// ─────────────────────────────────────────────────────────────────────────────

	private handleIconSlotChange = () => {
		this.hasSlottedIcon = this.host.querySelector('[slot="icon"]') !== null;
	};

	private handleGlobalDragCleanup = () => {
		this.isActive = false;
	};

	// ─────────────────────────────────────────────────────────────────────────────
	// RENDER
	// ─────────────────────────────────────────────────────────────────────────────

	render() {
		// Use resolvedContent (with dragId interpolation) or fall back to content prop
		const displayContent = this.resolvedContent || this.content;

		return (
			<Host
				class={{
					"hbr-drag-ghost": true,
					"hbr-drag-ghost--active": this.isActive,
					"hbr-drag-ghost--card": true,
					"has-slotted-icon": this.hasSlottedIcon,
				}}
			>
				{!this.hasSlottedIcon && (
					<span class="hbr-drag-ghost__icon">
						<slot name="icon" onSlotchange={this.handleIconSlotChange} />
					</span>
				)}

				{displayContent && (
					<span class="hbr-drag-ghost__content">{displayContent}</span>
				)}
				<slot />
			</Host>
		);
	}
}
